/* Same Bearer auth as Chat Retention; passes the request body through. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true, body: req.body || {} } }];

/* Error-rate alert check (priority 6, Langfuse-minimal).
   ALL data access via the n8n public API (helpers.httpRequest) — the same
   pattern as Chat Retention — because direct pg queries inside task-runner
   Code nodes crash the runner on any DatabaseError (read-only 'name' on the
   pg-protocol error object kills the runner process).

   Window: last ALERT_WINDOW_MIN minutes of chat_executions rows (fetched
   newest-first, filtered by createdAt in code). Fires an ops_alerts row when
   total >= ALERT_MIN_TOTAL and error rate >= ALERT_RATE_THRESHOLD, with
   ALERT_COOLDOWN_MIN cooldown. mode='list' returns recent alerts. */
const item = $input.first().json;
const body = item.body || {};
const mode = body.mode || 'check';

const WINDOW_MIN = Number($env.ALERT_WINDOW_MIN || 60);
const THRESHOLD = Number($env.ALERT_RATE_THRESHOLD || 0.5);
const MIN_TOTAL = Number($env.ALERT_MIN_TOTAL || 5);
const COOLDOWN_MIN = Number($env.ALERT_COOLDOWN_MIN || 60);
const API = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: API + path, headers: H, qs, body: payload });
const filterEq = (col, value) => JSON.stringify({ type: 'and', filters: [{ columnName: col, condition: 'eq', value }] });

try {
  const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
  const byName = {};
  for (const t of tables) byName[t.name] = t.id;
  const execId = byName['chat_executions'];
  const alertsId = byName['ops_alerts'];
  if (!execId || !alertsId) {
    return [{ json: { ok: false, mode, error: 'chat_executions / ops_alerts data tables missing (run deploy.mjs)' } }];
  }

  if (mode === 'list') {
    const rows = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 20, sortBy: 'createdAt:desc' })).data || [];
    return [{ json: { ok: true, mode, alerts: rows } }];
  }

  // ---- mode: check ----
  // fetch newest chat_executions rows (data table rows API), filter window in code
  const rows = (await api('GET', `/data-tables/${execId}/rows`, { limit: 250, sortBy: 'createdAt:desc' })).data || [];
  const cutoff = Date.now() - WINDOW_MIN * 60000;
  let total = 0;
  let errors = 0;
  for (const row of rows) {
    const t = Date.parse(row.createdAt || '');
    if (!(t >= cutoff)) break; // rows arrive newest-first
    total += 1;
    if (row.status === 'error') errors += 1;
  }
  const rate = total > 0 ? errors / total : 0;

  let alertFired = false;
  let skipReason = null;
  if (total >= MIN_TOTAL && rate >= THRESHOLD) {
    const lastRows = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 1, sortBy: 'createdAt:desc' })).data || [];
    const lastAt = lastRows.length ? Date.parse(lastRows[0].createdAt || '') || 0 : 0;
    if (Date.now() - lastAt >= COOLDOWN_MIN * 60000) {
      const message = '错误率 ' + (rate * 100).toFixed(1) + '%（' + errors + '/' + total + '，窗口 ' + WINDOW_MIN + ' 分钟）超过阈值 ' + (THRESHOLD * 100) + '%';
      await api('POST', `/data-tables/${alertsId}/rows`, null, { data: [{
        kind: 'error_rate',
        window_minutes: WINDOW_MIN,
        total,
        errors,
        error_rate: Math.round(rate * 1000) / 1000,
        threshold: THRESHOLD,
        message,
      }] });
      alertFired = true;
    } else {
      skipReason = 'cooldown';
    }
  } else if (total < MIN_TOTAL) {
    skipReason = 'below min total';
  }

  return [{ json: {
    ok: true,
    mode: 'check',
    window_minutes: WINDOW_MIN,
    total,
    errors,
    error_rate: Math.round(rate * 1000) / 1000,
    threshold: THRESHOLD,
    min_total: MIN_TOTAL,
    alert_fired: alertFired,
    ...(skipReason ? { skip_reason: skipReason } : {}),
    checked_at: new Date().toISOString(),
  } }];
} catch (e) {
  return [{ json: { ok: false, mode, error: String(e && e.message ? e.message : e).slice(0, 300) } }];
}
